def _find(required, extra=None):
    pats = ['/kaggle/input/' + '*/' * d + required for d in range(1, 5)]   # no recursive walk into the DICOM tree
    hits = sorted({Path(p).parent for pat in pats for p in glob.glob(pat)})
    if extra:
        hits = [h for h in hits if (h / extra).exists()]
    assert len(hits) == 1, (required, hits)
    return hits[0]


