def make_fake(root, ids):
    root.mkdir(parents=True, exist_ok=True)
    keep = set(ids)
    t = _tr[_tr[UIDK].isin(keep)].drop_duplicates(UIDK).set_index(UIDK).loc[ids].reset_index()
    t.to_csv(root / 'train.csv', index=False)
    se = pd.read_csv(_DATA / 'train_series.csv', dtype={UIDK: str, 'SeriesInstanceUID': str})
    se[se[UIDK].isin(keep)].to_csv(root / 'train_series.csv', index=False)
    if not (root / 'train_series').exists():
        os.symlink(_DATA / 'train_series', root / 'train_series')
    hdr = list(pd.read_csv(_DATA / 'sample_submission.csv', nrows=1).columns)
    ss = pd.DataFrame({c: 0.5 for c in hdr[1:]}, index=range(len(ids)))
    ss.insert(0, hdr[0], ids)
    ss.to_csv(root / 'sample_submission.csv', index=False)
    return hdr[1:]


