def _snapshot():
    """incremental copy of whatever the R6 workers have written (a killed session still leaves results)."""
    for f in sorted(_PRED.glob('worker*/predictions.csv')):
        shutil.copyfile(f, WORK / ('partial_r6_%s_shard%d.csv' % (f.parent.name, SHARD)))


def _snap_loop():
    while True:
        time.sleep(300)
        try:
            _snapshot()
        except Exception as e:
            print('snapshot failed', repr(e), flush=True)


threading.Thread(target=_snap_loop, daemon=True).start()

