r_t0 = time.time()
reader_status = 'not run'
try:
    assets = _find('knee.py', 'cnxt_v0_fold0.pt')
    ck = sorted(glob.glob(str(assets / 'cnxt_v0_fold[012].pt')))
    assert len(ck) == 3, ck
    env = dict(os.environ)
    target = _TMPBASE / '_own_env'
    subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', '--no-index', '--no-deps', '--target', str(target),
                    '--find-links', str(assets), 'pylibjpeg', 'pylibjpeg-libjpeg', 'pylibjpeg-openjpeg', 'pyjpegls',
                    'python-gdcm'], check=False)
    env['PYTHONPATH'] = str(target) + os.pathsep + env.get('PYTHONPATH', '')
    import torch
    ng = max(1, torch.cuda.device_count())
    halves = [SHARD_IDS[i::ng] for i in range(ng)]
    procs = []
    for g, part in enumerate(halves):
        root = _TMPBASE / ('pubkd_fake_r%d' % g)
        make_fake(root, part)
        e = dict(env, CUDA_VISIBLE_DEVICES=str(g))
        left = max(60, READER_DEADLINE_HOURS * 3600 - (time.time() - KERNEL_T0))
        procs.append((g, subprocess.Popen([sys.executable, str(OWN / 'infer.py'), str(root), 'train',
                                           str(_TMPBASE / ('_own_%d.csv' % g))] + ck, env=e), left))
    for g, p, left in procs:
        p.wait(timeout=left)
        assert p.returncode == 0, ('reader process', g, p.returncode)
    rd = pd.concat([pd.read_csv(_TMPBASE / ('_own_%d.csv' % g), dtype={UIDK: str}) for g in range(ng)])
    rd = rd.set_index(UIDK).loc[SHARD_IDS].reset_index()
    rd.to_csv(WORK / ('reader_train_shard%d.csv' % SHARD), index=False)
    reader_status = 'ok %d rows' % len(rd)
except Exception as e:
    reader_status = 'FAILED ' + repr(e)[:400]
print('READER', reader_status, 'seconds', round(time.time() - r_t0), flush=True)
rec = {'shard': SHARD, 'nshard': NSHARD, 'limit': LIMIT, 'studies': len(SHARD_IDS), 'r6_scored': len(rows),
       'r6_fallback_ids': fb, 'r6_seconds': round(R6_SECONDS, 1), 'r6_s_per_study_wall': round(R6_SECONDS / max(1, len(rows)), 2),
       'reader': reader_status, 'reader_seconds': round(time.time() - r_t0, 1),
       'r6_manifest_sha256': hashlib.sha256((M_SRC / 'manifest.json').read_bytes()).hexdigest(),
       'gpus': torch.cuda.device_count() if 'torch' in dir() else None, 'controller_receipt': receipt}
(WORK / ('receipt_shard%d.json' % SHARD)).write_text(json.dumps(rec, indent=1, default=str))
print('PUBKD_TEACHER_DONE', json.dumps({k: v for k, v in rec.items() if k not in ('controller_receipt', 'r6_fallback_ids')}), flush=True)
